int manacher(char* s, int n) {
    static char t[N << 1];
    static int p[N << 1];
    int m = 0;
    t[m++] = '#';
    for (int i = 0; i < n; i++) { t[m++] = s[i]; t[m++] = '#'; }
    int mx = 0, id = 0, ans = 0;
    for (int i = 0; i < m; i++) {
        p[i] = mx > i ? std::min(p[2 * id - i], mx - i) : 1;
        while (i - p[i] >= 0 && i + p[i] < m && t[i - p[i]] == t[i + p[i]]) p[i]++;
        if (i + p[i] > mx) { mx = i + p[i]; id = i; }
        ans = std::max(ans, p[i] - 1);
    }
    return ans;
}

