        for (int j = 0; j < 2; j++)
            for (int k = 0; k < 2; k++)
                C.a[i][j] = (C.a[i][j] + A.a[i][k] * B.a[k][j]) % MOD;
    return C;
}
Mat qpow(Mat A, ll b) {
    Mat res;
    res.a[0][0] = res.a[1][1] = 1;
    while (b) {
        if (b & 1) res = res * A;
        A = A * A;
        b >>= 1;
    }
    return res;
}

int gauss(double a[N][N], double b[N], int n) {
    for (int i = 1; i <= n; i++) {
        int p = i;
        for (int j = i + 1; j <= n; j++)
            if (fabs(a[j][i]) > fabs(a[p][i])) p = j;
        if (fabs(a[p][i]) < 1e-8) return 0;
        std::swap(a[i], a[p]); std::swap(b[i], b[p]);
        for (int j = 1; j <= n; j++) {
            if (j == i) continue;
            double t = a[j][i] / a[i][i];
            for (int k = i; k <= n; k++) a[j][k] -= a[i][k] * t;
            b[j] -= b[i] * t;
        }
    }
    for (int i = 1; i <= n; i++) b[i] /= a[i][i];
    return 1;
}

